-- Try-Hard Guide checks for the aLogs Beta Menu, from scripts/beta-seed-try-hard-guide.json: things read from the
-- game files that only an in-game test can confirm. INSERT OR IGNORE keeps any test the owner already reworded;
-- sort 100+ lists them after the 0.1.28-RC43 tests. created_at/updated_at 1793318400 = 2026-10-29 00:00 UTC.
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-break-hits-pet', '0.1.28-RC43', 'Hits to BREAK a pet', 'In a duel, BREAK a friend''s Lv 50 Aniimo using only Fire Kick from a Lv 50 Flameruff with 20 BREAK potential and no BREAK buffs: expect about 19 kicks.', '["From the game files: a pet''s BREAK bar is about 27,900 at Lv 50 (52,800 at Lv 70), and each hit takes your BREAK × the skill''s Might ÷ 10 off it (Flameruff''s BREAK 208 × Fire Kick''s 7.2 ≈ 1,500).","Any Aniimo works: expected hits ≈ the target''s BREAK bar ÷ (your BREAK × the skill''s Might ÷ 10). A crit takes off 1.5× as much.","Report the number of hits, both levels, your BREAK stat, the skill, whether any hit crit, and whether it was a duel or the Holo-Battle Simulator."]', 100, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-magic-mdef', '0.1.28-RC43', 'Magical skills hit M.DEF', 'Hit the same target with a Physical and a Magical skill of similar Might. Pick a target whose P.DEF and M.DEF are far apart (see its Aniimo page).', '["Expected: Magical hits are cut by the target''s M.DEF, Physical hits by its P.DEF.","Report both hit numbers, both skills and the target."]', 101, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-amp-vs-reduction', '0.1.28-RC43', 'Damage Amp and Damage Reduction cancel', 'With +20% Damage Amp up (e.g. Emberpup''s Fire Kick after a dodge), hit a target in Helmut''s Ballistic Guard (20% Damage Reduction): the hit should match one with neither.', '["The game puts Damage Amp and the target''s Damage Reduction in one pot: 1 + 0.2 − 0.2 = ×1. If they multiplied, the hit would be ×0.96.","Report the hits with both effects, with neither, and with each one alone if you can."]', 102, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-type-bonus', '0.1.28-RC43', 'Basic attack bonus multiplies with Damage Amp', 'Use Ignitis''s Dark Dash (+40% basic attack damage) together with Glacy''s Glimmer Shot (+15% Damage Amp): basic attacks should do ×1.61 (1.4 × 1.15), not ×1.55.', '["Report a basic attack''s damage with neither, with each, and with both."]', 103, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-break-bonus', '0.1.28-RC43', 'Bonus damage on a BREAKed target', 'With Pawney''s Ironclad Armament up, hit a target in BREAK, then the same target in BREAK without it: expect 30% more with it.', '["Report the hits and which skill you used."]', 104, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-inspiration', '0.1.28-RC43', 'Sparkelf''s Inspiration: the real number', 'Hit with a Fire skill with and without Sparkelf''s Inspiration: the game data says +30% Fire damage, the skill text says 15–18%.', '["Report both hits, the skill and Sparkelf''s level."]', 105, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-energized', '0.1.28-RC43', 'Hummin''s Energized: the real number', 'Hummin''s BREAK damage: the game data says +2.5% per 1,000 max HP, the trait text says 2%.', '["Compare how much of a target''s BREAK bar one Hummin hit removes against the expected BREAK × Might ÷ 10, and note Hummin''s max HP."]', 106, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-whole-team', '0.1.28-RC43', 'Whole-team buffs reach benched Aniimo', 'Cast Tromber''s Zephyr''s Breath or Sparkelf''s Inspiration, then switch in an Aniimo that was on the bench: it should have the buff.', '["Report whether the buff icon shows on the switched-in Aniimo and whether its hits are stronger."]', 107, 1793318400, 1793318400);
INSERT OR IGNORE INTO beta_tests (test_id, build, title, how, details, sort, created_at, updated_at) VALUES ('thg-level-gap', '0.1.28-RC43', 'Damage at a level gap', 'Hit the same kind of target at your level and about 10 levels above you, with the same skill: note both hits.', '["The game has a level-gap table; which part of it applies to players isn''t in the game files you install.","Report your level, both targets'' levels and the hit numbers."]', 108, 1793318400, 1793318400);
